package com.autoreview.cutter;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import com.arthenica.ffmpegkit.*;
public class MainActivity extends Activity {
 ArrayList<File> videos=new ArrayList<>(),audios=new ArrayList<>(); TextView status; ProgressBar bar; Button go; File pending; int V=10,A=11,S=12;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(25,35,25,20);l.setBackgroundColor(0xff171923);TextView t=new TextView(this);t.setText("AUTO REVIEW CUTTER");t.setTextColor(-1);t.setTextSize(23);l.addView(t);button(l,"Chọn nhiều video",()->pick("video/*",V));button(l,"Chọn audio",()->pick("audio/*",A));go=button(l,"TẠO VIDEO MP4",this::start);bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);l.addView(bar);status=new TextView(this);status.setTextColor(-1);status.setText("Chọn video và audio");l.addView(status);setContentView(l);}
 Button button(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);l.addView(b);b.setOnClickListener(v->r.run());return b;}
 void pick(String type,int req){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType(type);i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,req);}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;try{if(req==S){try(InputStream in=new FileInputStream(pending);OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}say("Đã lưu Review_Final.mp4");return;}ArrayList<Uri> list=new ArrayList<>();if(data.getClipData()!=null)for(int j=0;j<data.getClipData().getItemCount();j++)list.add(data.getClipData().getItemAt(j).getUri());else list.add(data.getData());for(Uri uri:list){File f=new File(getCacheDir(),"input"+System.nanoTime()+(req==V?".mp4":".audio"));try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);} (req==V?videos:audios).add(f);}say("Video: "+videos.size()+" | Audio: "+audios.size());}catch(Exception e){say("Lỗi đọc/lưu: "+e.getMessage());}}
 void say(String s){runOnUiThread(()->status.setText(s));}
 static String q(File f){return "'"+f.getAbsolutePath().replace("'","'\\''")+"'";}
 void cmd(String args)throws Exception{FFmpegSession s=FFmpegKit.execute(args);if(!ReturnCode.isSuccess(s.getReturnCode()))throw new Exception("FFmpeg thất bại: "+s.getAllLogsAsString());}
 double duration(File f)throws Exception{MediaInformationSession s=FFprobeKit.getMediaInformation(q(f));if(s.getMediaInformation()==null)throw new Exception("Không đọc được thời lượng");return Double.parseDouble(s.getMediaInformation().getDuration());}
 void start(){if(videos.isEmpty()||audios.isEmpty()){say("Cần chọn video và audio");return;}go.setEnabled(false);new Thread(()->{try{render();}catch(Exception e){say("Lỗi: "+e.getMessage());}finally{runOnUiThread(()->go.setEnabled(true));}}).start();}
 void render()throws Exception{File dir=new File(getCacheDir(),"work"+System.currentTimeMillis());dir.mkdirs();ArrayList<File> audioParts=new ArrayList<>();for(int i=0;i<audios.size();i++){File out=new File(dir,"a"+i+".wav");cmd("-y -i "+q(audios.get(i))+" -vn -ar 48000 -ac 2 -c:a pcm_s16le "+q(out));audioParts.add(out);}File alist=new File(dir,"audio.txt");try(PrintWriter w=new PrintWriter(alist)){for(File f:audioParts)w.println("file "+q(f));}File merged=new File(dir,"Audio_Merged.m4a");say("Đang nối audio...");cmd("-y -f concat -safe 0 -i "+q(alist)+" -af volume=10dB,alimiter=limit=0.95 -c:a aac -b:a 192k "+q(merged));double total=duration(merged);int n=(int)Math.ceil(total/4);if(n>5000)throw new Exception("Audio quá dài");ArrayList<File> parts=new ArrayList<>();double[] positions=new double[videos.size()];double[] lengths=new double[videos.size()];for(int j=0;j<videos.size();j++)lengths[j]=duration(videos.get(j));for(int i=0;i<n;i++){double seconds=Math.min(4,total-i*4.0);int chosen=-1;for(int j=0;j<videos.size();j++){int k=(i+j)%videos.size();if(lengths[k]>=seconds){chosen=k;break;}}if(chosen<0)throw new Exception("Video nguồn quá ngắn");if(positions[chosen]+seconds>lengths[chosen])positions[chosen]=0;File part=new File(dir,String.format(java.util.Locale.US,"v%05d.mp4",i));cmd(String.format(java.util.Locale.US,"-y -ss %.3f -i %s -t %.3f -an -vf scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2,fps=30,format=yuv420p -c:v libx264 -preset ultrafast -crf 23 %s",positions[chosen],q(videos.get(chosen)),seconds,q(part)));positions[chosen]+=seconds+0.3;parts.add(part);final int p=(int)((i+1)*100.0/n);runOnUiThread(()->bar.setProgress(p));say("Đang cắt cảnh "+(i+1)+"/"+n);}File vlist=new File(dir,"video.txt");try(PrintWriter w=new PrintWriter(vlist)){for(File f:parts)w.println("file "+q(f));}File video=new File(dir,"video.mp4");cmd("-y -f concat -safe 0 -i "+q(vlist)+" -c copy "+q(video));File output=new File(dir,"Review_Final.mp4");cmd(String.format(java.util.Locale.US,"-y -i %s -i %s -map 0:v:0 -map 1:a:0 -c:v copy -c:a aac -t %.3f -movflags +faststart %s",q(video),q(merged),total,q(output)));pending=output;runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("video/mp4");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"Review_Final.mp4");startActivityForResult(intent,S);});}
}